fromEuler.example:
// a quarter turn around the world's up axis
const facing = kcds.math.Quaternion.fromEuler(0, 0, Math.PI / 2);
npc.rotation = facing;

fromEuler.exampleCs:
// a quarter turn around the world's up axis
var facing = Quaternion.FromEuler(0, 0, Math.PI / 2);
npc.Rotation = facing;

fromAxisAngle.example:
// A quarter turn to the left around the world's up axis (+Z).
const turn = kcds.math.Quaternion.fromAxisAngle(new kcds.math.Vector3(0, 0, 1), Math.PI / 2);
npc.rotation = npc.rotation.clone().mul(turn);

fromAxisAngle.exampleCs:
// A quarter turn to the left around the world's up axis (+Z).
var turn = Quaternion.FromAxisAngle(new Vector3(0, 0, 1), Math.PI / 2);
npc.Rotation = npc.Rotation.Clone().Mul(turn);

inverse.example:
const turn = kcds.math.Quaternion.fromEuler(0, 0, Math.PI / 2);
const back = turn.inverse();
const same = back.rotateVector(turn.rotateVector(new kcds.math.Vector3(1, 0, 0))); // Vector3(1, 0, 0) again, give or take rounding

inverse.exampleCs:
var turn = Quaternion.FromEuler(0, 0, Math.PI / 2);
var back = turn.Inverse();
var same = back.RotateVector(turn.RotateVector(new Vector3(1, 0, 0))); // Vector3(1, 0, 0) again, give or take rounding

rotateVector.example:
// The direction a player faces: the world's +Y turned by their rotation.
const facing = player.rotation.rotateVector(new kcds.math.Vector3(0, 1, 0));
const inFront = player.position.clone().add(facing.mul(2));

rotateVector.exampleCs:
// The direction a player faces: the world's +Y turned by their rotation.
var facing = player.Rotation.RotateVector(new Vector3(0, 1, 0));
var inFront = player.Position.Clone().Add(facing.Mul(2));
